const mongoose = require("mongoose");
const DataStore = require("./models/DataStore");
const Vet = require("./models/Vet");
const User = require("./models/User");
const Pet = require("./models/Pet");
const Appointment = require("./models/Appointment");
const Consultation = require("./models/Consultation");
const Prescription = require("./models/Prescription");
const ChatMessage = require("./models/ChatMessage");

mongoose.connect("mongodb://localhost:27017/petcare")
.then(function() {
  console.log("Connected to MongoDB for Seeding");
  return seedDB();
}).catch(function(err) {
  console.error("DB Connection Error:", err);
  process.exit(1);
});

function seedDB() {
  console.log("Clearing master_data collection...");
  // Clear the master data collection since everything is inside it now
  return DataStore.deleteMany({})
  .then(function() {
    console.log("Seeding Users (5 records)...");
    return User.insertMany([
      { name: "Rahul Verma", email: "rahul@example.com", phone: "9876543211", password: "password123", role: "owner" },
      { name: "Priya Sharma", email: "priya@example.com", phone: "9876543212", password: "password123", role: "owner" },
      { name: "Amit Kumar", email: "amit@example.com", phone: "9876543213", password: "password123", role: "owner" },
      { name: "Sneha Reddy", email: "sneha@example.com", phone: "9876543214", password: "password123", role: "owner" },
      { name: "Karthik Nair", email: "karthik@example.com", phone: "9876543215", password: "password123", role: "owner" }
    ]);
  })
  .then(function(users) {
    console.log("Seeding Pets (5 records)...");
    return Pet.insertMany([
      { ownerId: users[0]._id, ownerName: users[0].name, ownerEmail: users[0].email, ownerPhone: users[0].phone, name: "Sheru", species: "Dog", breed: "Indian Pariah", age: 3, weight: 15, gender: "Male" },
      { ownerId: users[1]._id, ownerName: users[1].name, ownerEmail: users[1].email, ownerPhone: users[1].phone, name: "Luna", species: "Dog", breed: "Golden Retriever", age: 2, weight: 22, gender: "Female" },
      { ownerId: users[2]._id, ownerName: users[2].name, ownerEmail: users[2].email, ownerPhone: users[2].phone, name: "Milo", species: "Cat", breed: "Calico", age: 4, weight: 5, gender: "Male" },
