import React from 'react'
import { Routes, Route, Navigate } from 'react-router-dom'

// We will import pages here as we build them.
// For now, we'll render a simple placeholder to test the setup.

const Placeholder = ({ title }) => (
  <div className="p-8 text-center">
    <h1 className="text-2xl font-bold text-primary">{title}</h1>
    <p>Component is under construction.</p>
  </div>
);

function App() {
  return (
    <Routes>
      <Route path="/" element={<Placeholder title="Home" />} />
      <Route path="*" element={<Navigate to="/" replace />} />
    </Routes>
  )
}

export default App

import React from 'react';
import { NavLink, Link, useNavigate } from 'react-router-dom';

const OwnerSidebar = () => {
  const navigate = useNavigate();

  const handleLogout = (e) => {
    e.preventDefault();
    localStorage.removeItem('userToken');
    localStorage.removeItem('currentUser');
    navigate('/');
  };

  const navLinkClass = ({ isActive }) =>
    `nav-link flex items-center gap-md px-sm py-2 rounded-lg transition-all ${
      isActive
        ? 'bg-secondary-container text-on-secondary-container font-bold scale-[0.98]'
        : 'text-on-surface-variant hover:bg-surface-container'
    }`;

  return (
    <nav className="bg-surface border-r border-outline-variant hidden md:flex flex-col h-screen w-[280px] p-md gap-base fixed left-0 top-0 z-40">
      {/* Header Brand */}
      <Link to="/" className="flex items-center gap-sm mb-lg px-2">
        <span className="material-symbols-outlined text-primary text-3xl filled-icon">pets</span>
        <div>
          <h1 className="font-headline-sm text-headline-sm font-black text-primary">
            Paws<span className="text-[#FF9933]">India</span> 🇮🇳
          </h1>
          <p className="font-label-md text-xs text-on-surface-variant">Veterinary Portal</p>
        </div>
      </Link>

      {/* Main Nav Links */}
      <div className="flex flex-col gap-xs flex-grow">
        <NavLink to="/owner-dashboard" className={navLinkClass}>
          <span className="material-symbols-outlined filled-icon">dashboard</span>
          <span className="font-label-md text-label-md">Dashboard</span>
        </NavLink>
        <NavLink to="/find-vets" className={navLinkClass}>
          <span className="material-symbols-outlined">search</span>
          <span className="font-label-md text-label-md">Find Vets</span>
        </NavLink>
        <NavLink to="/my-pets" className={navLinkClass}>
          <span className="material-symbols-outlined">pets</span>
          <span className="font-label-md text-label-md">My Pets</span>
        </NavLink>
        <NavLink to="/appointments" className={navLinkClass}>
          <span className="material-symbols-outlined">calendar_today</span>
          <span className="font-label-md text-label-md">Appointments</span>
        </NavLink>
        <NavLink to="/prescription" className={navLinkClass}>
          <span className="material-symbols-outlined">medical_services</span>
          <span className="font-label-md text-label-md">Prescriptions</span>
        </NavLink>
      </div>

      {/* Footer Actions */}
      <div className="flex flex-col gap-xs mt-auto">
        <Link to="/find-vets" className="w-full bg-[#FF7F50] text-white font-label-md text-label-md py-sm rounded-lg font-bold mb-sm hover:opacity-90 transition-opacity text-center block">
          Book Appointment
        </Link>
        <button className="flex items-center gap-md px-sm py-2 text-on-surface-variant hover:bg-surface-container transition-all rounded-lg w-full text-left">
          <span className="material-symbols-outlined">help</span>
          <span className="font-label-md text-label-md">Help</span>
        </button>
        <button onClick={handleLogout} className="flex items-center gap-md px-sm py-2 text-on-surface-variant hover:bg-surface-container transition-all rounded-lg cursor-pointer w-full text-left">
          <span className="material-symbols-outlined">logout</span>
          <span className="font-label-md text-label-md">Logout</span>
        </button>
      </div>
    </nav>
  );
};

export default OwnerSidebar;

import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';

const TopNav = ({ title, subtitle, backLink }) => {
  const [user, setUser] = useState({ name: 'User' });

  useEffect(() => {
    const storedUser = localStorage.getItem('currentUser');
    if (storedUser) {
      setUser(JSON.parse(storedUser));
    }
  }, []);

  const firstName = user.name.split(' ')[0];

  return (
    <header className="flex justify-between items-center w-full no-print mb-lg">
      <div>
        {backLink ? (
          <Link to={backLink.to} className="flex items-center gap-xs text-on-surface-variant hover:text-primary transition-colors font-body-sm font-semibold mb-2">
            <span className="material-symbols-outlined text-[18px]">arrow_back</span> {backLink.text}
          </Link>
        ) : null}

        <h2 className="font-headline-lg text-headline-lg-mobile md:text-headline-lg text-on-surface">
          {title || `Welcome back, ${firstName}! 👋`}
        </h2>
        {subtitle && (
          <p className="text-on-surface-variant font-body-sm text-body-sm">
            {subtitle}
          </p>
        )}
      </div>

      <div className="hidden md:flex items-center gap-md">
        <button className="w-10 h-10 flex items-center justify-center rounded-full hover:bg-surface-container-high transition-colors text-on-surface-variant relative" title="Notifications">
          <span className="material-symbols-outlined">notifications</span>
          <span className="w-2.5 h-2.5 bg-error rounded-full absolute top-2 right-2 border-2 border-background"></span>
        </button>
        <div className="w-10 h-10 rounded-full overflow-hidden border border-outline-variant cursor-pointer bg-surface-container">
          <img 
            alt="User Profile" 
            className="w-full h-full object-cover" 
            src={user.photoUrl || "https://images.unsplash.com/photo-1534528741775-53994a69daeb?w=100&auto=format&fit=crop"}
            onError={(e) => { e.target.src = "https://images.unsplash.com/photo-1534528741775-53994a69daeb?w=100&auto=format&fit=crop"; }}
          />
        </div>
      </div>
    </header>
  );
};

export default TopNav;

import React, { useState, useEffect } from 'react';
