        <div className="min-w-0 flex-1">
          <h2 className="font-headline-sm text-xs font-bold text-primary truncate">{vet.name}</h2>
          <p className="text-[11px] text-on-surface-variant truncate font-medium">{vet.vciNumber || 'N/A'}</p>
