                    ))}
                    {vet.specialization && vet.specialization.length > 2 && (
                      <span className="text-[10px] uppercase tracking-wider font-bold bg-surface-container text-on-surface-variant px-2 py-1 rounded-md border border-outline-variant">
                        +{vet.specialization.length - 2}
                      </span>
                    )}
                  </div>

                  <div className="mt-auto pt-4 border-t border-outline-variant/50 flex items-center justify-between">
                    <div className="flex flex-col">
                      <span className="text-[10px] text-on-surface-variant uppercase font-bold tracking-wider">Consult Fee</span>
                      <span className="font-bold text-primary">₹{vet.consultationFee || 499}</span>
                    </div>
                    <Link to={`/vet-profile?id=${vet._id}`} className="bg-primary text-on-primary px-4 py-2 rounded-lg text-sm font-bold shadow-sm hover:bg-surface-tint transition-colors">
                      Book Visit
                    </Link>
                  </div>
                </div>
              </div>
            ))
          ) : (
            <div className="col-span-full py-16 text-center text-on-surface-variant">
              No veterinarians found.
            </div>
          )}
        </div>
      </main>
    </div>
  );
};

export default FindVets;

import React, { useState, useEffect } from 'react';
import { useSearchParams, useNavigate } from 'react-router-dom';
import OwnerSidebar from '../components/OwnerSidebar';
import TopNav from '../components/TopNav';

const VetProfile = () => {
  const [searchParams] = useSearchParams();
  const vetId = searchParams.get('id');
  const navigate = useNavigate();

  const [vet, setVet] = useState(null);
  const [loading, setLoading] = useState(true);
  const [bookingLoading, setBookingLoading] = useState(false);

  const [date, setDate] = useState('');
  const [time, setTime] = useState('');
  const [type, setType] = useState('video');
  const [reason, setReason] = useState('');

  useEffect(() => {
    if (!vetId) {
      navigate('/find-vets');
      return;
    }

    const fetchVet = async () => {
      try {
        const res = await fetch(`http://localhost:5000/api/vets/${vetId}`);
        if (res.ok) {
          const data = await res.json();
          setVet(data.data);
        }
      } catch (err) {
        console.error("Error fetching vet details", err);
      } finally {
        setLoading(false);
      }
    };
    fetchVet();
  }, [vetId, navigate]);

  const handleBooking = async (e) => {
    e.preventDefault();
    if (!date || !time || !type) {
      alert("Please select date, time, and type of consultation.");
      return;
    }

    const storedUser = localStorage.getItem('currentUser');
    if (!storedUser) {
      alert("Please login to book an appointment");
      navigate('/login');
      return;
    }

    setBookingLoading(true);
    try {
      const user = JSON.parse(storedUser);
      const payload = {
        vetId: vet._id,
        vetName: vet.name,
        vetSpecialization: vet.qualification,
        ownerId: user._id || "guest",
        ownerName: user.name || "Pet Parent",
        ownerPhone: user.phone || "+91 00000 00000",
        petName: "My Pet", // Ideally selected from a dropdown
        petSpecies: "Dog",
        petBreed: "Mixed",
        petAge: "3 years",
        petWeight: "15 kg",
        petSex: "Male",
        date: date,
        time: time,
        consultationType: type,
        reasonForVisit: reason,
        fee: vet.consultationFee || 499,
        status: 'upcoming'
      };

      const res = await fetch('http://localhost:5000/api/consultations', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload)
      });

      const json = await res.json();

      if (res.ok && json.success) {
        alert(`Consultation with ${vet.name} confirmed!\nDate: ${date}\nTime: ${time}`);
        navigate('/appointments');
      } else {
        alert(json.message || "Failed to book consultation");
      }
    } catch (err) {
      alert("Error booking consultation: " + err.message);
    } finally {
      setBookingLoading(false);
    }
  };

  if (loading) {
    return (
      <div className="bg-background text-on-background font-body-md min-h-screen flex">
        <OwnerSidebar />
        <main className="flex-grow ml-0 md:ml-[280px] flex items-center justify-center">
          <span className="material-symbols-outlined animate-spin text-4xl text-primary">sync</span>
        </main>
      </div>
    );
  }

  if (!vet) return null;

  return (
    <div className="bg-background text-on-background font-body-md min-h-screen flex">
      <OwnerSidebar />

      <main className="flex-grow ml-0 md:ml-[280px] p-4 md:p-8 pb-12 md:pb-8 flex flex-col gap-6 max-w-[1280px] mx-auto w-full">
        <TopNav backLink={{ to: '/find-vets', text: 'Back to Vets Directory' }} />

        <div className="grid grid-cols-1 lg:grid-cols-12 gap-6 w-full">
          {/* Left Column: Doctor Bio */}
          <div className="lg:col-span-7 flex flex-col gap-6">
            <div className="bg-surface-container-lowest border border-outline-variant rounded-2xl p-6 shadow-sm ambient-shadow">
              <div className="flex flex-col sm:flex-row gap-6 items-start">
                <div className="w-32 h-32 rounded-2xl overflow-hidden shrink-0 border-2 border-primary/20 shadow-md relative bg-surface-container">
                  <img src={vet.photoUrl || "https://images.unsplash.com/photo-1559839734-2b71ea197ec2?w=500&auto=format&fit=crop"} alt={vet.name} className="w-full h-full object-cover" />
                  <span className="absolute bottom-1 right-1 w-4 h-4 bg-emerald-500 rounded-full border-2 border-white" title="Online for Telehealth"></span>
                </div>
                <div className="flex-1">
                  <div className="flex flex-wrap items-center gap-2 mb-1">
                    <h2 className="font-headline-lg text-xl md:text-2xl text-on-surface font-bold">{vet.name}</h2>
                    <span className="material-symbols-outlined text-primary filled-icon text-[22px]" title="Verified Veterinary Specialist">verified</span>
                    <span className="font-mono text-xs text-emerald-800 bg-emerald-100 px-2.5 py-0.5 rounded-full font-bold border border-emerald-200">
                      {vet.vciNumber || 'VCI Verified'}
                    </span>
                  </div>
                  <p className="font-body-md text-sm text-on-surface-variant mb-4 font-semibold">{vet.qualification}</p>

                  <div className="flex flex-wrap gap-2 mb-4">
                    <div className="flex items-center gap-1 bg-secondary-container/40 text-on-secondary-container px-3 py-1 rounded-full text-xs font-bold">
                      <span className="material-symbols-outlined text-[16px]">location_on</span>
                      {vet.city || 'India'} • {vet.experienceYears || '0'} Yrs Exp.
                    </div>
                    <div className="flex items-center gap-1 bg-amber-50 text-amber-800 border border-amber-200 px-3 py-1 rounded-full text-xs font-bold">
                      <span className="material-symbols-outlined text-[16px]">star</span>
                      4.9 (120+ Reviews)
                    </div>
                  </div>
                </div>
              </div>

              <div className="mt-6 pt-6 border-t border-outline-variant">
                <h3 className="font-headline-sm text-lg font-bold text-on-surface mb-3 flex items-center gap-2">
                  <span className="material-symbols-outlined text-primary">person</span> Professional Profile & Bio
                </h3>
                <p className="font-body-md text-sm text-on-surface-variant leading-relaxed">
                  {vet.about || "Loading profile details..."}
                </p>
              </div>

              {vet.specialization && vet.specialization.length > 0 && (
                <div className="mt-6 pt-6 border-t border-outline-variant">
                  <h3 className="font-headline-sm text-lg font-bold text-on-surface mb-3 flex items-center gap-2">
                    <span className="material-symbols-outlined text-primary">local_hospital</span> Specializations
                  </h3>
                  <div className="flex flex-wrap gap-2">
                    {vet.specialization.map((spec, i) => (
                      <span key={i} className="bg-surface-container-low border border-outline-variant text-on-surface-variant px-3 py-1.5 rounded-lg text-xs font-semibold flex items-center gap-1.5">
                        <span className="w-1.5 h-1.5 rounded-full bg-primary"></span> {spec}
                      </span>
                    ))}
                  </div>
                </div>
              )}
            </div>
          </div>

          {/* Right Column: Booking Widget */}
          <div className="lg:col-span-5">
            <div className="bg-surface-container-lowest border border-outline-variant rounded-2xl shadow-lg ambient-shadow overflow-hidden sticky top-24">
              <div className="bg-primary p-4 text-on-primary">
                <h3 className="font-headline-sm font-bold text-lg flex items-center gap-2">
                  <span className="material-symbols-outlined">edit_calendar</span> Book Consultation
                </h3>
                <p className="text-xs text-primary-fixed opacity-90 mt-1">Instant confirmation & secure payment.</p>
              </div>

              <div className="p-6">
                <form onSubmit={handleBooking} className="flex flex-col gap-6">
                  {/* Select Consultation Type */}
                  <div className="flex flex-col gap-2">
                    <label className="font-label-md text-xs font-bold text-on-surface uppercase tracking-wider">1. Consultation Type</label>
                    <div className="grid grid-cols-2 gap-3">
                      <label className={`border rounded-xl p-3 cursor-pointer transition-all flex flex-col items-center gap-1 text-center ${type === 'video' ? 'bg-primary/5 border-primary text-primary shadow-sm' : 'border-outline-variant bg-surface-container-lowest text-on-surface-variant hover:bg-surface-container-low'}`}>
                        <input type="radio" name="cons_type" value="video" checked={type === 'video'} onChange={() => setType('video')} className="hidden" />
                        <span className="material-symbols-outlined text-[24px]">videocam</span>
                        <span className="font-bold text-xs">Video Call</span>
                      </label>
                      <label className={`border rounded-xl p-3 cursor-pointer transition-all flex flex-col items-center gap-1 text-center ${type === 'clinic' ? 'bg-primary/5 border-primary text-primary shadow-sm' : 'border-outline-variant bg-surface-container-lowest text-on-surface-variant hover:bg-surface-container-low'}`}>
                        <input type="radio" name="cons_type" value="clinic" checked={type === 'clinic'} onChange={() => setType('clinic')} className="hidden" />
                        <span className="material-symbols-outlined text-[24px]">storefront</span>
                        <span className="font-bold text-xs">Clinic Visit</span>
                      </label>
                    </div>
                  </div>

                  {/* Select Date & Time */}
                  <div className="flex flex-col gap-2">
                    <label className="font-label-md text-xs font-bold text-on-surface uppercase tracking-wider">2. Date & Time</label>
                    <div className="grid grid-cols-2 gap-3">
                      <input type="date" value={date} onChange={(e) => setDate(e.target.value)} required className="border border-outline-variant rounded-xl p-2.5 text-sm font-semibold text-on-surface focus:border-primary focus:ring-1 focus:ring-primary outline-none" />
                      <input type="time" value={time} onChange={(e) => setTime(e.target.value)} required className="border border-outline-variant rounded-xl p-2.5 text-sm font-semibold text-on-surface focus:border-primary focus:ring-1 focus:ring-primary outline-none" />
                    </div>
                  </div>

                  {/* Reason for Visit */}
                  <div className="flex flex-col gap-2">
                    <label className="font-label-md text-xs font-bold text-on-surface uppercase tracking-wider">3. Reason for Visit</label>
                    <textarea value={reason} onChange={(e) => setReason(e.target.value)} rows="2" className="border border-outline-variant rounded-xl p-3 text-sm text-on-surface focus:border-primary focus:ring-1 focus:ring-primary outline-none resize-none" placeholder="Briefly describe the issue..."></textarea>
                  </div>

                  {/* Price Breakdown */}
                  <div className="bg-surface-container-low p-4 rounded-xl border border-outline-variant/50">
                    <div className="flex justify-between items-center mb-2">
                      <span className="text-sm text-on-surface-variant">Consultation Fee</span>
                      <span className="font-bold text-on-surface">₹{vet.consultationFee || 499}</span>
                    </div>
                    <div className="flex justify-between items-center mb-2">
                      <span className="text-sm text-on-surface-variant">Platform Fee (Inc. GST)</span>
                      <span className="font-bold text-on-surface">₹50</span>
                    </div>
                    <div className="flex justify-between items-center pt-2 border-t border-outline-variant font-bold text-primary text-lg">
                      <span>Total Payable</span>
                      <span>₹{(vet.consultationFee || 499) + 50}</span>
                    </div>
                  </div>

                  {/* Submit */}
                  <button type="submit" disabled={bookingLoading} className="w-full bg-primary text-on-primary py-3.5 rounded-xl font-bold shadow-md hover:bg-surface-tint hover:-translate-y-0.5 transition-all flex justify-center items-center gap-2">
                    {bookingLoading ? (
                      <><span className="material-symbols-outlined animate-spin text-[20px]">sync</span> Processing...</>
                    ) : (
                      <><span className="material-symbols-outlined">event_available</span> Confirm & Pay ₹{(vet.consultationFee || 499) + 50}</>
                    )}
                  </button>
                  <p className="text-[10px] text-center text-on-surface-variant font-medium mt-[-8px]">
                    By booking, you agree to PawsIndia's Telehealth Terms of Service.
                  </p>
                </form>
              </div>
            </div>
          </div>
        </div>
      </main>
    </div>
  );
};

export default VetProfile;

import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import OwnerSidebar from '../components/OwnerSidebar';
import TopNav from '../components/TopNav';

const MyPets = () => {
  const [user, setUser] = useState(null);
  const [pets, setPets] = useState([]);
  const [loading, setLoading] = useState(true);
  const [addingPet, setAddingPet] = useState(false);
  const navigate = useNavigate();

  const [newPet, setNewPet] = useState({
    name: '',
    species: 'Dog',
    breed: '',
    age: '',
    weight: '',
    sex: 'Male'
  });

  useEffect(() => {
    const storedUser = localStorage.getItem('currentUser');
    if (!storedUser) {
      navigate('/login');
      return;
    }
    const parsedUser = JSON.parse(storedUser);
    setUser(parsedUser);
    fetchPets(parsedUser._id);
  }, [navigate]);

  const fetchPets = async (userId) => {
    try {
      const res = await fetch(`http://localhost:5000/api/pets/owner/${userId}`);
      if (res.ok) {
        const data = await res.json();
        setPets(data.data || []);
      }
    } catch (err) {
      console.error("Error fetching pets", err);
    } finally {
      setLoading(false);
    }
  };

  const handleAddPet = async (e) => {
    e.preventDefault();
    setAddingPet(true);

    try {
      const payload = { ...newPet, ownerId: user._id };
      const res = await fetch('http://localhost:5000/api/pets', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload)
      });
      const data = await res.json();

      if (res.ok && data.success) {
        setPets([...pets, data.data]);
        setNewPet({ name: '', species: 'Dog', breed: '', age: '', weight: '', sex: 'Male' });
        document.getElementById('addPetModal').classList.add('hidden');
      } else {
        alert(data.message || 'Failed to add pet');
      }
    } catch (err) {
      alert("Error adding pet: " + err.message);
    } finally {
      setAddingPet(false);
    }
  };

  const handleDeletePet = async (petId) => {
    if (!window.confirm("Are you sure you want to remove this pet profile?")) return;
    try {
      const res = await fetch(`http://localhost:5000/api/pets/${petId}`, { method: 'DELETE' });
      if (res.ok) {
        setPets(pets.filter(p => p._id !== petId));
      }
    } catch (err) {
      console.error("Error deleting pet", err);
    }
  };

  if (!user) return null;

  return (
    <div className="bg-background text-on-background font-body-md min-h-screen flex relative">
      <OwnerSidebar />

      <main className="flex-grow ml-0 md:ml-[280px] p-4 md:p-8 pb-12 md:pb-8 flex flex-col gap-6 max-w-[1280px] mx-auto w-full">
        <TopNav title="My Pets" subtitle="Manage your pet profiles and health records." />

        <div className="flex justify-between items-center bg-surface-container-low p-4 rounded-xl border border-outline-variant/50">
          <h2 className="font-headline-sm font-bold text-lg text-on-surface">Registered Pets ({pets.length})</h2>
          <button 
            onClick={() => document.getElementById('addPetModal').classList.remove('hidden')} 
            className="bg-primary text-on-primary px-4 py-2 rounded-lg font-bold text-sm shadow-sm flex items-center gap-2 hover:bg-surface-tint transition-colors"
          >
            <span className="material-symbols-outlined text-[20px]">add</span> Add New Pet
          </button>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {loading ? (
            <div className="col-span-full py-16 flex flex-col items-center justify-center text-on-surface-variant">
              <span className="material-symbols-outlined animate-spin text-primary text-4xl mb-4">sync</span>
              <span className="font-label-md text-base font-semibold">Loading Pets...</span>
            </div>
          ) : pets.length > 0 ? (
            pets.map(pet => (
              <div key={pet._id} className="bg-surface-container-lowest border border-outline-variant rounded-2xl overflow-hidden shadow-sm hover:shadow-md transition-all flex flex-col group">
                <div className="p-6 flex flex-col items-center border-b border-outline-variant/50 bg-gradient-to-b from-surface-container-low to-transparent relative">
                  <button onClick={() => handleDeletePet(pet._id)} className="absolute top-4 right-4 text-error hover:bg-error-container/20 p-2 rounded-full transition-colors" title="Delete Profile">
                    <span className="material-symbols-outlined text-[20px]">delete</span>
                  </button>
                  <div className="w-24 h-24 rounded-full border-4 border-white shadow-md overflow-hidden bg-white mb-4">
                    <img src={pet.species.toLowerCase() === 'cat' ? 'https://images.unsplash.com/photo-1514888286974-6c03e2ca1dba?w=200&auto=format&fit=crop' : 'https://images.unsplash.com/photo-1543466835-00a7907e9de1?w=200&auto=format&fit=crop'} alt={pet.name} className="w-full h-full object-cover" />
                  </div>
                  <h3 className="font-headline-sm font-bold text-xl text-on-surface">{pet.name}</h3>
                  <p className="font-label-md text-sm text-primary font-bold">{pet.breed}</p>
                </div>
                <div className="p-5 flex-grow bg-surface-container-lowest">
                  <div className="grid grid-cols-2 gap-4">
                    <div className="flex flex-col bg-surface-container-low p-2 rounded-lg border border-outline-variant/30">
                      <span className="text-[10px] uppercase font-bold text-on-surface-variant tracking-wider">Age</span>
                      <span className="font-bold text-on-surface">{pet.age}</span>
                    </div>
                    <div className="flex flex-col bg-surface-container-low p-2 rounded-lg border border-outline-variant/30">
                      <span className="text-[10px] uppercase font-bold text-on-surface-variant tracking-wider">Weight</span>
                      <span className="font-bold text-on-surface">{pet.weight}</span>
                    </div>
                    <div className="flex flex-col bg-surface-container-low p-2 rounded-lg border border-outline-variant/30">
                      <span className="text-[10px] uppercase font-bold text-on-surface-variant tracking-wider">Species</span>
                      <span className="font-bold text-on-surface">{pet.species}</span>
                    </div>
                    <div className="flex flex-col bg-surface-container-low p-2 rounded-lg border border-outline-variant/30">
                      <span className="text-[10px] uppercase font-bold text-on-surface-variant tracking-wider">Sex</span>
                      <span className="font-bold text-on-surface">{pet.sex}</span>
                    </div>
                  </div>
                </div>
              </div>
            ))
          ) : (
            <div className="col-span-full py-16 text-center text-on-surface-variant flex flex-col items-center">
              <span className="material-symbols-outlined text-6xl mb-2 opacity-50">pets</span>
              <p className="font-bold">No pets added yet.</p>
              <p className="text-sm">Add your first pet to start booking consultations.</p>
            </div>
          )}
        </div>
      </main>

      {/* Add Pet Modal */}
      <div id="addPetModal" className="fixed inset-0 z-50 hidden">
        <div className="absolute inset-0 bg-black/50 backdrop-blur-sm" onClick={() => document.getElementById('addPetModal').classList.add('hidden')}></div>
        <div className="absolute top-1/2 left-1/2 transform -translate-x-1/2 -translate-y-1/2 w-full max-w-lg bg-surface-container-lowest rounded-2xl shadow-xl overflow-hidden z-10 border border-outline-variant/30">
          <div className="px-6 py-4 border-b border-outline-variant/50 flex justify-between items-center bg-surface-container-low">
            <h3 className="font-headline-sm font-bold text-lg text-primary flex items-center gap-2">
              <span className="material-symbols-outlined">pets</span> Add New Pet Profile
            </h3>
            <button onClick={() => document.getElementById('addPetModal').classList.add('hidden')} className="text-on-surface-variant hover:text-error transition-colors">
              <span className="material-symbols-outlined">close</span>
            </button>
          </div>
          <form onSubmit={handleAddPet} className="p-6">
            <div className="grid grid-cols-2 gap-4">
              <div className="col-span-2">
                <label className="block text-xs font-bold font-label-md text-on-surface mb-1">Pet Name *</label>
