              </div>
              <div>
                <label className="block text-xs font-bold font-label-md text-on-surface mb-1">Species *</label>
                <select value={newPet.species} onChange={(e) => setNewPet({...newPet, species: e.target.value})} className="w-full px-3 py-2 border border-outline-variant rounded-lg focus:outline-none focus:border-primary text-sm">
                  <option value="Dog">Dog</option>
                  <option value="Cat">Cat</option>
                  <option value="Bird">Bird</option>
                  <option value="Rabbit">Rabbit</option>
                  <option value="Other">Other</option>
                </select>
              </div>
              <div>
                <label className="block text-xs font-bold font-label-md text-on-surface mb-1">Breed *</label>
                <input type="text" value={newPet.breed} onChange={(e) => setNewPet({...newPet, breed: e.target.value})} required className="w-full px-3 py-2 border border-outline-variant rounded-lg focus:outline-none focus:border-primary text-sm" placeholder="e.g. Golden Retriever" />
              </div>
              <div>
                <label className="block text-xs font-bold font-label-md text-on-surface mb-1">Age *</label>
                <input type="text" value={newPet.age} onChange={(e) => setNewPet({...newPet, age: e.target.value})} required className="w-full px-3 py-2 border border-outline-variant rounded-lg focus:outline-none focus:border-primary text-sm" placeholder="e.g. 2 years 3 months" />
              </div>
              <div>
                <label className="block text-xs font-bold font-label-md text-on-surface mb-1">Weight *</label>
                <input type="text" value={newPet.weight} onChange={(e) => setNewPet({...newPet, weight: e.target.value})} required className="w-full px-3 py-2 border border-outline-variant rounded-lg focus:outline-none focus:border-primary text-sm" placeholder="e.g. 15 kg" />
              </div>
              <div className="col-span-2">
                <label className="block text-xs font-bold font-label-md text-on-surface mb-1">Sex *</label>
                <div className="flex gap-4">
                  <label className="flex items-center gap-2 text-sm"><input type="radio" name="sex" value="Male" checked={newPet.sex === 'Male'} onChange={(e) => setNewPet({...newPet, sex: 'Male'})} /> Male</label>
                  <label className="flex items-center gap-2 text-sm"><input type="radio" name="sex" value="Female" checked={newPet.sex === 'Female'} onChange={(e) => setNewPet({...newPet, sex: 'Female'})} /> Female</label>
                </div>
              </div>
            </div>
            <div className="mt-6 flex justify-end gap-3">
              <button type="button" onClick={() => document.getElementById('addPetModal').classList.add('hidden')} className="px-4 py-2 border border-outline-variant text-on-surface-variant font-bold rounded-lg hover:bg-surface-container text-sm">Cancel</button>
              <button type="submit" disabled={addingPet} className="px-6 py-2 bg-primary text-white font-bold rounded-lg shadow-sm hover:bg-surface-tint text-sm flex items-center gap-2">
                {addingPet ? <><span className="material-symbols-outlined animate-spin text-[18px]">sync</span> Saving...</> : 'Save Pet Profile'}
              </button>
            </div>
          </form>
        </div>
      </div>
    </div>
  );
};

