import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import OwnerSidebar from '../components/OwnerSidebar';
import TopNav from '../components/TopNav';

const Appointments = () => {
  const [user, setUser] = useState(null);
  const [appointments, setAppointments] = useState([]);
  const [loading, setLoading] = useState(true);
  const navigate = useNavigate();

  useEffect(() => {
    const storedUser = localStorage.getItem('currentUser');
    if (!storedUser) {
      navigate('/login');
      return;
    }
    const parsedUser = JSON.parse(storedUser);
    setUser(parsedUser);
    fetchAppointments(parsedUser._id);
  }, [navigate]);

  const fetchAppointments = async (userId) => {
    try {
      const res = await fetch(`http://localhost:5000/api/consultations/owner/${userId}`);
      if (res.ok) {
        const data = await res.json();
        setAppointments(data.data || []);
      }
    } catch (err) {
      console.error("Error fetching appointments", err);
    } finally {
      setLoading(false);
    }
  };

  const handleCancel = async (id) => {
    if (!window.confirm("Are you sure you want to cancel this appointment?")) return;
    try {
      const res = await fetch(`http://localhost:5000/api/consultations/${id}`, { method: 'DELETE' });
      if (res.ok) {
        setAppointments(appointments.filter(a => a._id !== id));
      }
    } catch (err) {
      console.error("Error cancelling appointment", err);
    }
  };

  if (!user) return null;

  return (
    <div className="bg-background text-on-background font-body-md min-h-screen flex">
      <OwnerSidebar />

      <main className="flex-grow ml-0 md:ml-[280px] p-4 md:p-8 pb-12 md:pb-8 flex flex-col gap-6 max-w-[1280px] mx-auto w-full">
        <TopNav title="My Appointments" subtitle="Manage your upcoming and past vet consultations." />

        <div className="bg-surface-container-lowest border border-outline-variant rounded-2xl shadow-sm ambient-shadow overflow-hidden">
          <div className="p-6 border-b border-outline-variant flex justify-between items-center bg-surface-container-low">
            <h3 className="font-headline-sm font-bold text-lg flex items-center gap-2 text-on-surface">
              <span className="material-symbols-outlined text-primary">event_note</span> All Appointments
            </h3>
          </div>

          <div className="p-6">
            {loading ? (
              <div className="py-16 flex flex-col items-center justify-center text-on-surface-variant">
                <span className="material-symbols-outlined animate-spin text-primary text-4xl mb-4">sync</span>
                <span className="font-label-md text-base font-semibold">Loading Appointments...</span>
              </div>
            ) : appointments.length > 0 ? (
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                {appointments.map(appt => (
                  <div key={appt._id} className="border border-outline-variant rounded-xl p-5 hover:bg-surface-container-low transition-colors relative group">
                    <button onClick={() => handleCancel(appt._id)} className="absolute top-4 right-4 text-error opacity-0 group-hover:opacity-100 hover:bg-error-container/20 p-2 rounded-full transition-all" title="Cancel Appointment">
                      <span className="material-symbols-outlined text-[20px]">cancel</span>
                    </button>

                    <div className="flex justify-between items-start mb-3">
                      <div>
                        <h4 className="font-headline-sm font-bold text-lg text-on-surface">{appt.vetName}</h4>
                        <p className="text-xs text-on-surface-variant">{appt.vetSpecialization || 'Veterinarian'}</p>
                      </div>
                      <span className={`text-[10px] px-2 py-0.5 rounded font-bold uppercase border ${appt.status === 'upcoming' ? 'bg-emerald-50 text-emerald-700 border-emerald-200' : 'bg-surface-container-high text-on-surface-variant border-outline-variant'}`}>
                        {appt.status}
                      </span>
                    </div>

                    <div className="flex flex-col gap-2 bg-surface-container-lowest border border-outline-variant/30 rounded-lg p-3 mb-4">
                      <div className="flex items-center gap-2 text-sm text-on-surface font-medium">
                        <span className="material-symbols-outlined text-[16px] text-primary">pets</span> Pet: {appt.petName} ({appt.petSpecies})
                      </div>
                      <div className="flex items-center gap-4 text-xs text-on-surface-variant">
                        <span className="flex items-center gap-1"><span className="material-symbols-outlined text-[14px]">calendar_today</span> {appt.date}</span>
                        <span className="flex items-center gap-1"><span className="material-symbols-outlined text-[14px]">schedule</span> {appt.time}</span>
                      </div>
                    </div>

                    <div className="flex gap-2">
                      {appt.consultationType === 'video' ? (
                        <button className="flex-1 bg-primary text-white text-xs font-bold py-2 rounded-lg hover:bg-surface-tint transition-colors flex items-center justify-center gap-1">
                          <span className="material-symbols-outlined text-[16px]">videocam</span> Join Call
                        </button>
                      ) : (
                        <button className="flex-1 bg-secondary text-white text-xs font-bold py-2 rounded-lg hover:bg-secondary-fixed-dim transition-colors flex items-center justify-center gap-1">
                          <span className="material-symbols-outlined text-[16px]">directions</span> Get Directions
                        </button>
                      )}
                    </div>
                  </div>
                ))}
              </div>
            ) : (
              <div className="py-16 text-center text-on-surface-variant flex flex-col items-center">
                <span className="material-symbols-outlined text-6xl mb-2 opacity-50">calendar_today</span>
                <p className="font-bold">No appointments scheduled.</p>
                <p className="text-sm">Book a consultation with a verified vet today.</p>
              </div>
            )}
          </div>
        </div>
      </main>
    </div>
