import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import VetSidebar from '../components/VetSidebar';
import TopNav from '../components/TopNav';

const DoctorProfile = () => {
  const [user, setUser] = useState(null);
  const [isEditing, setIsEditing] = useState(false);
  const [formData, setFormData] = useState({});
  const [loading, setLoading] = useState(false);
  const navigate = useNavigate();

  useEffect(() => {
    const storedUser = localStorage.getItem('currentUser');
    if (!storedUser) {
      navigate('/login');
      return;
    }
    const parsedUser = JSON.parse(storedUser);
    setUser(parsedUser);
    setFormData({
      name: parsedUser.name || '',
      email: parsedUser.email || '',
      phone: parsedUser.phone || '',
      clinicName: parsedUser.clinicName || '',
      city: parsedUser.city || '',
      consultationFee: parsedUser.consultationFee || 499,
      about: parsedUser.about || '',
    });
  }, [navigate]);

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
  };

  const handleSave = async () => {
    setLoading(true);
    try {
      const res = await fetch(`http://localhost:5000/api/vets/${user._id}`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(formData)
      });
      const data = await res.json();
      if (res.ok && data.success) {
        const updatedUser = { ...user, ...formData };
        setUser(updatedUser);
        localStorage.setItem('currentUser', JSON.stringify(updatedUser));
        setIsEditing(false);
        alert('Profile updated successfully!');
      } else {
        alert(data.message || 'Update failed');
      }
    } catch (err) {
      alert("Error updating profile: " + err.message);
    } finally {
      setLoading(false);
    }
  };

  if (!user) return null;

  return (
    <div className="bg-background text-on-background font-body-md min-h-screen flex">
      <VetSidebar />

      <main className="flex-grow ml-0 md:ml-[280px] p-4 md:p-8 pb-12 md:pb-8 flex flex-col gap-6 max-w-[1280px] mx-auto w-full">
        <TopNav title="Doctor Profile" subtitle="Manage your professional details and clinic information." />

        <div className="bg-surface-container-lowest border border-outline-variant rounded-2xl shadow-sm ambient-shadow overflow-hidden">
          {/* Cover & Avatar Header */}
          <div className="h-32 bg-primary/20 relative">
            <div className="absolute -bottom-12 left-8">
              <div className="w-24 h-24 rounded-full border-4 border-surface-container-lowest overflow-hidden bg-white shadow-md">
                <img src={user.photoUrl || "https://images.unsplash.com/photo-1559839734-2b71ea197ec2?w=200&auto=format&fit=crop"} alt={user.name} className="w-full h-full object-cover" />
              </div>
            </div>
            <div className="absolute top-4 right-4">
              {!isEditing ? (
                <button onClick={() => setIsEditing(true)} className="bg-white/80 backdrop-blur-sm border border-white/50 text-primary px-4 py-2 rounded-lg font-bold text-sm shadow-sm flex items-center gap-2 hover:bg-white transition-colors">
                  <span className="material-symbols-outlined text-[18px]">edit</span> Edit Profile
                </button>
              ) : (
                <div className="flex gap-2">
                  <button onClick={() => setIsEditing(false)} className="bg-white/80 backdrop-blur-sm border border-white/50 text-on-surface-variant px-4 py-2 rounded-lg font-bold text-sm shadow-sm hover:bg-white transition-colors">
                    Cancel
                  </button>
                  <button onClick={handleSave} disabled={loading} className="bg-primary text-white px-4 py-2 rounded-lg font-bold text-sm shadow-sm flex items-center gap-2 hover:bg-surface-tint transition-colors">
                    {loading ? <><span className="material-symbols-outlined animate-spin text-[18px]">sync</span> Saving...</> : 'Save Changes'}
                  </button>
                </div>
              )}
            </div>
          </div>

          <div className="pt-16 px-8 pb-8">
            <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
              {/* Form Fields */}
              <div className="space-y-4">
                <h3 className="font-headline-sm font-bold text-lg border-b border-outline-variant/30 pb-2 mb-4">Personal Details</h3>

                <div>
                  <label className="block text-xs font-bold font-label-md text-on-surface mb-1">Full Name</label>
                  <input type="text" name="name" value={formData.name} onChange={handleChange} disabled={!isEditing} className={`w-full px-3 py-2 border rounded-lg text-sm transition-all ${isEditing ? 'border-outline-variant bg-surface-container-lowest focus:border-primary focus:outline-none focus:ring-1' : 'border-transparent bg-surface-container-low text-on-surface-variant cursor-not-allowed'}`} />
                </div>

                <div className="grid grid-cols-2 gap-4">
                  <div>
                    <label className="block text-xs font-bold font-label-md text-on-surface mb-1">Email</label>
                    <input type="email" name="email" value={formData.email} onChange={handleChange} disabled={!isEditing} className={`w-full px-3 py-2 border rounded-lg text-sm transition-all ${isEditing ? 'border-outline-variant bg-surface-container-lowest focus:border-primary focus:outline-none focus:ring-1' : 'border-transparent bg-surface-container-low text-on-surface-variant cursor-not-allowed'}`} />
                  </div>
                  <div>
                    <label className="block text-xs font-bold font-label-md text-on-surface mb-1">Phone</label>
                    <input type="tel" name="phone" value={formData.phone} onChange={handleChange} disabled={!isEditing} className={`w-full px-3 py-2 border rounded-lg text-sm transition-all ${isEditing ? 'border-outline-variant bg-surface-container-lowest focus:border-primary focus:outline-none focus:ring-1' : 'border-transparent bg-surface-container-low text-on-surface-variant cursor-not-allowed'}`} />
                  </div>
                </div>

                <div>
                  <label className="block text-xs font-bold font-label-md text-on-surface mb-1">Professional Bio</label>
                  <textarea name="about" value={formData.about} onChange={handleChange} disabled={!isEditing} rows="4" className={`w-full px-3 py-2 border rounded-lg text-sm transition-all resize-none ${isEditing ? 'border-outline-variant bg-surface-container-lowest focus:border-primary focus:outline-none focus:ring-1' : 'border-transparent bg-surface-container-low text-on-surface-variant cursor-not-allowed'}`}></textarea>
                </div>
              </div>

              <div className="space-y-4">
                <h3 className="font-headline-sm font-bold text-lg border-b border-outline-variant/30 pb-2 mb-4 flex items-center justify-between">
                  Clinic & Practice
                  <span className="text-xs bg-emerald-100 text-emerald-800 px-2 py-0.5 rounded font-bold uppercase border border-emerald-200">VCI Verified</span>
                </h3>

                <div>
                  <label className="block text-xs font-bold font-label-md text-on-surface mb-1">VCI Registration Number</label>
                  <input type="text" value={user.vciNumber || 'VCI-XXXX-XXXX'} disabled className="w-full px-3 py-2 border border-transparent bg-surface-container-low text-on-surface-variant rounded-lg text-sm font-mono cursor-not-allowed" />
                </div>

                <div>
                  <label className="block text-xs font-bold font-label-md text-on-surface mb-1">Primary Qualification</label>
                  <input type="text" value={user.qualification || ''} disabled className="w-full px-3 py-2 border border-transparent bg-surface-container-low text-on-surface-variant rounded-lg text-sm cursor-not-allowed" />
                </div>

                <div>
                  <label className="block text-xs font-bold font-label-md text-on-surface mb-1">Clinic Name</label>
                  <input type="text" name="clinicName" value={formData.clinicName} onChange={handleChange} disabled={!isEditing} className={`w-full px-3 py-2 border rounded-lg text-sm transition-all ${isEditing ? 'border-outline-variant bg-surface-container-lowest focus:border-primary focus:outline-none focus:ring-1' : 'border-transparent bg-surface-container-low text-on-surface-variant cursor-not-allowed'}`} />
                </div>

                <div className="grid grid-cols-2 gap-4">
                  <div>
                    <label className="block text-xs font-bold font-label-md text-on-surface mb-1">City</label>
                    <input type="text" name="city" value={formData.city} onChange={handleChange} disabled={!isEditing} className={`w-full px-3 py-2 border rounded-lg text-sm transition-all ${isEditing ? 'border-outline-variant bg-surface-container-lowest focus:border-primary focus:outline-none focus:ring-1' : 'border-transparent bg-surface-container-low text-on-surface-variant cursor-not-allowed'}`} />
                  </div>
                  <div>
                    <label className="block text-xs font-bold font-label-md text-on-surface mb-1">Consultation Fee (₹)</label>
                    <input type="number" name="consultationFee" value={formData.consultationFee} onChange={handleChange} disabled={!isEditing} className={`w-full px-3 py-2 border rounded-lg text-sm transition-all font-bold ${isEditing ? 'border-outline-variant bg-surface-container-lowest focus:border-primary focus:outline-none focus:ring-1 text-primary' : 'border-transparent bg-surface-container-low text-on-surface-variant cursor-not-allowed'}`} />
                  </div>
                </div>
              </div>
            </div>
          </div>
        </div>
      </main>
    </div>
  );
};

export default DoctorProfile;

import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import VetSidebar from '../components/VetSidebar';
import TopNav from '../components/TopNav';

const VetAppointments = () => {
  const [user, setUser] = useState(null);
  const [appointments, setAppointments] = useState([]);
  const [loading, setLoading] = useState(true);
  const navigate = useNavigate();

  useEffect(() => {
    const storedUser = localStorage.getItem('currentUser');
    if (!storedUser) {
      navigate('/login');
      return;
    }
    const parsedUser = JSON.parse(storedUser);
    setUser(parsedUser);
    fetchAppointments(parsedUser._id);
  }, [navigate]);

  const fetchAppointments = async (vetId) => {
    try {
      const res = await fetch(`http://localhost:5000/api/consultations/vet/${vetId}`);
      if (res.ok) {
        const data = await res.json();
        setAppointments(data.data || []);
      }
    } catch (err) {
      console.error("Error fetching appointments", err);
    } finally {
      setLoading(false);
    }
  };

  const handleUpdateStatus = async (id, status) => {
    try {
      const res = await fetch(`http://localhost:5000/api/consultations/${id}/status`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ status })
      });
      if (res.ok) {
        setAppointments(appointments.map(a => a._id === id ? { ...a, status } : a));
      }
    } catch (err) {
      console.error("Error updating status", err);
    }
  };

  if (!user) return null;

  return (
    <div className="bg-background text-on-background font-body-md min-h-screen flex">
      <VetSidebar />

      <main className="flex-grow ml-0 md:ml-[280px] p-4 md:p-8 pb-12 md:pb-8 flex flex-col gap-6 max-w-[1280px] mx-auto w-full">
        <TopNav title="Schedule & Appointments" subtitle="Manage your clinical queue and telehealth calls." />

        <div className="bg-surface-container-lowest border border-outline-variant rounded-2xl shadow-sm ambient-shadow overflow-hidden">
          <div className="p-6 border-b border-outline-variant flex justify-between items-center bg-surface-container-low">
            <h3 className="font-headline-sm font-bold text-lg flex items-center gap-2 text-on-surface">
              <span className="material-symbols-outlined text-primary">calendar_month</span> All Appointments
            </h3>
            <div className="flex gap-2">
              <button className="px-3 py-1.5 bg-primary text-on-primary rounded font-bold text-xs shadow-sm">Upcoming</button>
              <button className="px-3 py-1.5 bg-surface-container text-on-surface-variant border border-outline-variant/50 rounded font-bold text-xs">Completed</button>
            </div>
          </div>

          <div className="p-6">
            {loading ? (
              <div className="py-16 flex flex-col items-center justify-center text-on-surface-variant">
                <span className="material-symbols-outlined animate-spin text-primary text-4xl mb-4">sync</span>
                <span className="font-label-md text-base font-semibold">Loading Schedule...</span>
              </div>
            ) : appointments.length > 0 ? (
              <div className="flex flex-col gap-4">
                {appointments.map(appt => (
                  <div key={appt._id} className={`border rounded-xl p-5 hover:bg-surface-container-low transition-colors ${appt.status === 'upcoming' ? 'border-primary/50 bg-primary/5' : 'border-outline-variant'}`}>
                    <div className="flex flex-col md:flex-row justify-between md:items-start gap-4">

                      <div className="flex-grow">
                        <div className="flex justify-between items-start mb-2">
                          <h4 className="font-headline-sm font-bold text-lg text-on-surface">{appt.petName} <span className="text-sm font-normal text-on-surface-variant">({appt.petSpecies})</span></h4>
                          <span className={`text-[10px] px-2 py-0.5 rounded font-bold uppercase border ${appt.status === 'upcoming' ? 'bg-emerald-50 text-emerald-700 border-emerald-200' : 'bg-surface-container-high text-on-surface-variant border-outline-variant'}`}>
                            {appt.status}
                          </span>
                        </div>
                        <p className="text-sm text-on-surface mb-1"><strong>Parent:</strong> {appt.ownerName} • {appt.ownerPhone}</p>
                        <p className="text-xs text-on-surface-variant bg-surface-container-low p-2 rounded-lg border border-outline-variant/30 mb-3"><strong>Reason:</strong> {appt.reasonForVisit || 'Not specified'}</p>
                        <div className="flex items-center gap-4 text-xs text-on-surface-variant font-bold">
                          <span className="flex items-center gap-1"><span className="material-symbols-outlined text-[14px]">calendar_today</span> {appt.date}</span>
                          <span className="flex items-center gap-1"><span className="material-symbols-outlined text-[14px]">schedule</span> {appt.time}</span>
                          <span className="flex items-center gap-1 bg-secondary-container/30 text-on-secondary-container px-2 rounded">
                            <span className="material-symbols-outlined text-[14px]">{appt.consultationType === 'video' ? 'videocam' : 'storefront'}</span> 
                            {appt.consultationType === 'video' ? 'Telehealth' : 'Clinic'}
                          </span>
                        </div>
                      </div>

                      <div className="flex md:flex-col gap-2 shrink-0 md:min-w-[150px]">
                        {appt.status === 'upcoming' && (
                          <>
                            {appt.consultationType === 'video' && (
                              <button className="flex-1 bg-primary text-white text-xs font-bold py-2 px-3 rounded-lg hover:bg-surface-tint transition-colors flex items-center justify-center gap-1">
                                <span className="material-symbols-outlined text-[16px]">videocam</span> Join Call
                              </button>
                            )}
                            <button 
                              onClick={() => handleUpdateStatus(appt._id, 'completed')}
                              className="flex-1 bg-surface-container-high border border-outline-variant text-on-surface text-xs font-bold py-2 px-3 rounded-lg hover:bg-surface-container transition-colors flex items-center justify-center gap-1"
                            >
                              <span className="material-symbols-outlined text-[16px]">check</span> Mark Done
                            </button>
                            <button 
                              onClick={() => handleUpdateStatus(appt._id, 'cancelled')}
                              className="flex-1 text-error text-xs font-bold py-2 px-3 hover:bg-error-container/20 rounded-lg transition-colors flex items-center justify-center gap-1"
                            >
                              Cancel
                            </button>
                          </>
                        )}
                        {appt.status === 'completed' && (
                          <button className="flex-1 bg-surface-container-low border border-outline-variant text-primary text-xs font-bold py-2 px-3 rounded-lg hover:bg-surface-container transition-colors flex items-center justify-center gap-1">
                            <span className="material-symbols-outlined text-[16px]">prescriptions</span> Prescribe
                          </button>
                        )}
                      </div>
                    </div>
                  </div>
                ))}
              </div>
            ) : (
              <div className="py-16 text-center text-on-surface-variant flex flex-col items-center">
                <span className="material-symbols-outlined text-6xl mb-2 opacity-50">calendar_month</span>
                <p className="font-bold">No appointments found.</p>
              </div>
            )}
          </div>
        </div>
      </main>
    </div>
  );
};

export default VetAppointments;

import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import VetSidebar from '../components/VetSidebar';
import TopNav from '../components/TopNav';

const Prescribe = () => {
  const [user, setUser] = useState(null);
  const [appointments, setAppointments] = useState([]);
  const [selectedAppt, setSelectedAppt] = useState('');

  const [formData, setFormData] = useState({
    diagnosis: '',
    medicines: [{ name: '', dosage: '', frequency: '', duration: '' }],
    instructions: ''
  });
  const [submitting, setSubmitting] = useState(false);
  const navigate = useNavigate();

  useEffect(() => {
    const storedUser = localStorage.getItem('currentUser');
    if (!storedUser) {
      navigate('/login');
      return;
    }
    const parsedUser = JSON.parse(storedUser);
    setUser(parsedUser);
    fetchAppointments(parsedUser._id);
  }, [navigate]);

  const fetchAppointments = async (vetId) => {
    try {
      const res = await fetch(`http://localhost:5000/api/consultations/vet/${vetId}`);
      if (res.ok) {
        const data = await res.json();
        // Only completed appointments need prescriptions usually, or we can just list all
        setAppointments(data.data || []);
      }
    } catch (err) {
      console.error("Error fetching appointments", err);
    }
  };

  const handleMedChange = (index, field, value) => {
    const newMeds = [...formData.medicines];
    newMeds[index][field] = value;
    setFormData({ ...formData, medicines: newMeds });
  };

  const addMedicine = () => {
    setFormData({
      ...formData,
      medicines: [...formData.medicines, { name: '', dosage: '', frequency: '', duration: '' }]
    });
  };

  const removeMedicine = (index) => {
    const newMeds = formData.medicines.filter((_, i) => i !== index);
    setFormData({ ...formData, medicines: newMeds });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!selectedAppt) {
      alert("Please select a patient/appointment");
      return;
    }

    setSubmitting(true);
    try {
      const appt = appointments.find(a => a._id === selectedAppt);
      const payload = {
        consultationId: appt._id,
        vetId: user._id,
        ownerId: appt.ownerId,
        petName: appt.petName,
        diagnosis: formData.diagnosis,
        medicines: formData.medicines,
        instructions: formData.instructions
      };

      const res = await fetch('http://localhost:5000/api/prescriptions', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload)
      });
      const data = await res.json();

      if (res.ok && data.success) {
        alert('Prescription created successfully!');
        navigate('/doctor-dashboard');
      } else {
        alert(data.message || 'Failed to create prescription');
      }
    } catch (err) {
      alert("Error: " + err.message);
    } finally {
      setSubmitting(false);
    }
  };

  if (!user) return null;

  return (
    <div className="bg-background text-on-background font-body-md min-h-screen flex">
      <VetSidebar />

      <main className="flex-grow ml-0 md:ml-[280px] p-4 md:p-8 pb-12 md:pb-8 flex flex-col gap-6 max-w-[1280px] mx-auto w-full">
        <TopNav title="Digital Prescription" subtitle="Write and send digital Rx securely to pet parents." />

        <div className="bg-surface-container-lowest border border-outline-variant rounded-2xl shadow-sm ambient-shadow overflow-hidden max-w-4xl mx-auto w-full">
          <div className="p-6 border-b border-outline-variant bg-surface-container-low flex justify-between items-center">
            <div>
              <h3 className="font-headline-sm font-bold text-lg text-primary flex items-center gap-2">
                <span className="material-symbols-outlined">prescriptions</span> Rx pad
              </h3>
              <p className="text-xs text-on-surface-variant font-bold font-mono mt-1">{user.vciNumber || 'VCI Verified'}</p>
            </div>
            <div className="text-right">
              <p className="font-bold text-sm">{user.name}</p>
              <p className="text-xs text-on-surface-variant">{user.qualification}</p>
            </div>
          </div>

          <form onSubmit={handleSubmit} className="p-6 space-y-6">

            <div className="space-y-4">
              <h4 className="font-bold text-sm border-b border-outline-variant/30 pb-2">Patient Details</h4>
              <div>
                <label className="block text-xs font-bold font-label-md text-on-surface mb-1">Select Consultation *</label>
                <select 
                  value={selectedAppt} 
                  onChange={(e) => setSelectedAppt(e.target.value)} 
                  required 
                  className="w-full px-3 py-2 border border-outline-variant rounded-lg focus:outline-none focus:border-primary text-sm bg-surface-container-lowest"
                >
                  <option value="">-- Choose Patient / Appointment --</option>
                  {appointments.map(appt => (
                    <option key={appt._id} value={appt._id}>
                      {appt.petName} ({appt.petSpecies}) - Parent: {appt.ownerName} - {appt.date} {appt.time}
                    </option>
                  ))}
                </select>
              </div>

              <div>
                <label className="block text-xs font-bold font-label-md text-on-surface mb-1">Clinical Diagnosis *</label>
                <input 
                  type="text" 
                  value={formData.diagnosis} 
                  onChange={(e) => setFormData({...formData, diagnosis: e.target.value})} 
                  required 
                  placeholder="e.g. Mild Gastroenteritis"
                  className="w-full px-3 py-2 border border-outline-variant rounded-lg focus:outline-none focus:border-primary text-sm bg-surface-container-lowest"
                />
              </div>
            </div>

            <div className="space-y-4">
              <div className="flex justify-between items-center border-b border-outline-variant/30 pb-2">
                <h4 className="font-bold text-sm">Medications (Rx)</h4>
                <button type="button" onClick={addMedicine} className="text-xs font-bold text-primary flex items-center gap-1 hover:bg-primary/5 px-2 py-1 rounded">
                  <span className="material-symbols-outlined text-[16px]">add</span> Add Medicine
                </button>
              </div>

              <div className="space-y-3">
                {formData.medicines.map((med, index) => (
                  <div key={index} className="grid grid-cols-1 md:grid-cols-12 gap-3 items-start bg-surface-container-low/50 p-3 rounded-xl border border-outline-variant/30 relative">
                    {formData.medicines.length > 1 && (
                      <button type="button" onClick={() => removeMedicine(index)} className="absolute -top-2 -right-2 bg-error text-white rounded-full w-5 h-5 flex items-center justify-center shadow hover:bg-error-container hover:text-error transition-colors">
                        <span className="material-symbols-outlined text-[12px]">close</span>
                      </button>
                    )}
                    <div className="md:col-span-4">
                      <label className="block text-[10px] font-bold text-on-surface-variant uppercase mb-1">Medicine Name</label>
                      <input type="text" value={med.name} onChange={(e) => handleMedChange(index, 'name', e.target.value)} required placeholder="e.g. Metronidazole" className="w-full px-3 py-1.5 border border-outline-variant rounded-lg text-sm bg-surface-container-lowest" />
                    </div>
                    <div className="md:col-span-2">
                      <label className="block text-[10px] font-bold text-on-surface-variant uppercase mb-1">Dosage</label>
                      <input type="text" value={med.dosage} onChange={(e) => handleMedChange(index, 'dosage', e.target.value)} required placeholder="e.g. 5ml" className="w-full px-3 py-1.5 border border-outline-variant rounded-lg text-sm bg-surface-container-lowest" />
                    </div>
                    <div className="md:col-span-3">
                      <label className="block text-[10px] font-bold text-on-surface-variant uppercase mb-1">Frequency</label>
                      <input type="text" value={med.frequency} onChange={(e) => handleMedChange(index, 'frequency', e.target.value)} required placeholder="e.g. Twice a day (BD)" className="w-full px-3 py-1.5 border border-outline-variant rounded-lg text-sm bg-surface-container-lowest" />
                    </div>
                    <div className="md:col-span-3">
                      <label className="block text-[10px] font-bold text-on-surface-variant uppercase mb-1">Duration</label>
                      <input type="text" value={med.duration} onChange={(e) => handleMedChange(index, 'duration', e.target.value)} required placeholder="e.g. 5 days" className="w-full px-3 py-1.5 border border-outline-variant rounded-lg text-sm bg-surface-container-lowest" />
                    </div>
                  </div>
                ))}
              </div>
            </div>

            <div className="space-y-4">
              <h4 className="font-bold text-sm border-b border-outline-variant/30 pb-2">Doctor's Advice / Diet</h4>
              <textarea 
                value={formData.instructions} 
                onChange={(e) => setFormData({...formData, instructions: e.target.value})} 
                rows="3" 
                placeholder="Specific instructions for rest, diet, or next follow-up..."
                className="w-full px-3 py-2 border border-outline-variant rounded-lg focus:outline-none focus:border-primary text-sm bg-surface-container-lowest resize-none"
              ></textarea>
            </div>

            <div className="pt-4 border-t border-outline-variant flex justify-end gap-3">
              <button type="button" onClick={() => navigate('/doctor-dashboard')} className="px-6 py-2 border border-outline-variant text-on-surface-variant font-bold rounded-xl hover:bg-surface-container text-sm transition-colors">
                Cancel
              </button>
              <button type="submit" disabled={submitting} className="px-8 py-2 bg-primary text-on-primary font-bold rounded-xl shadow-sm hover:bg-surface-tint text-sm transition-colors flex items-center gap-2">
                {submitting ? <><span className="material-symbols-outlined animate-spin text-[18px]">sync</span> Saving...</> : <><span className="material-symbols-outlined text-[18px]">send</span> Send Prescription</>}
              </button>
            </div>
            <p className="text-[10px] text-center text-on-surface-variant font-medium">
              By submitting this prescription, you confirm that you have evaluated the patient and are authorized to prescribe under VCI regulations.
            </p>
          </form>
        </div>
      </main>
    </div>
  );
};

export default Prescribe;

