import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import OwnerSidebar from '../components/OwnerSidebar';
import TopNav from '../components/TopNav';

const Prescription = () => {
  const [user, setUser] = useState(null);
  const [prescriptions, setPrescriptions] = useState([]);
  const [loading, setLoading] = useState(true);
  const navigate = useNavigate();

  useEffect(() => {
    const storedUser = localStorage.getItem('currentUser');
    if (!storedUser) {
      navigate('/login');
      return;
    }
    const parsedUser = JSON.parse(storedUser);
    setUser(parsedUser);
    fetchPrescriptions(parsedUser._id);
  }, [navigate]);

  const fetchPrescriptions = async (ownerId) => {
    try {
      // In a real app we'd have a specific endpoint for this, e.g. /api/prescriptions/owner/:id
      // but for this mock, let's just fetch all and filter, or assume it exists.
      const res = await fetch(`http://localhost:5000/api/prescriptions`);
      if (res.ok) {
        const data = await res.json();
        // Assuming we need to filter by ownerId if API returns all
        const myRx = (data.data || []).filter(rx => rx.ownerId === ownerId);
        setPrescriptions(myRx);
      }
    } catch (err) {
      console.error("Error fetching prescriptions", err);
    } finally {
      setLoading(false);
    }
  };

  if (!user) return null;

  return (
    <div className="bg-background text-on-background font-body-md min-h-screen flex">
      <OwnerSidebar />

      <main className="flex-grow ml-0 md:ml-[280px] p-4 md:p-8 pb-12 md:pb-8 flex flex-col gap-6 max-w-[1280px] mx-auto w-full">
