import React, { useState, useEffect, useRef } from 'react';
import { useNavigate } from 'react-router-dom';
import OwnerSidebar from '../components/OwnerSidebar';

const LiveChat = () => {
  const [messages, setMessages] = useState([
    { id: 1, text: "Hello! This is Dr. Sharma. How is Bella feeling today?", sender: 'doctor', time: '10:00 AM' },
    { id: 2, text: "Hi Doctor. She's still a bit lethargic and hasn't eaten much.", sender: 'user', time: '10:05 AM' },
    { id: 3, text: "I see. Did she vomit again after the morning medicine?", sender: 'doctor', time: '10:06 AM' }
  ]);
  const [input, setInput] = useState('');
  const messagesEndRef = useRef(null);
  const navigate = useNavigate();

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages]);

  const handleSend = (e) => {
    e.preventDefault();
    if (!input.trim()) return;

    const newMsg = {
      id: Date.now(),
      text: input,
      sender: 'user',
      time: new Date().toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'})
    };

    setMessages([...messages, newMsg]);
    setInput('');

    // Simulate doctor reply
    setTimeout(() => {
      setMessages(prev => [...prev, {
        id: Date.now(),
        text: "Understood. Please keep an eye on her water intake. We will connect on the telehealth call shortly.",
        sender: 'doctor',
        time: new Date().toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'})
      }]);
    }, 2000);
  };

  return (
    <div className="bg-background text-on-background font-body-md min-h-screen flex">
      <OwnerSidebar />

      <main className="flex-grow ml-0 md:ml-[280px] h-screen flex flex-col">
        {/* Chat Header */}
        <header className="h-16 bg-surface-container-lowest border-b border-outline-variant/30 px-6 flex items-center justify-between shrink-0">
          <div className="flex items-center gap-4">
            <button onClick={() => navigate(-1)} className="md:hidden flex items-center text-on-surface-variant hover:text-primary transition-colors">
              <span className="material-symbols-outlined">arrow_back</span>
            </button>
            <div className="flex items-center gap-3">
              <div className="relative">
                <img src="https://images.unsplash.com/photo-1559839734-2b71ea197ec2?w=100&auto=format&fit=crop" alt="Dr. Sharma" className="w-10 h-10 rounded-full object-cover border border-outline-variant/30" />
                <span className="absolute bottom-0 right-0 w-3 h-3 bg-emerald-500 border-2 border-white rounded-full"></span>
              </div>
              <div>
                <h2 className="font-bold text-sm text-on-surface">Dr. Ananya Sharma</h2>
                <p className="text-[11px] text-primary font-bold">Veterinarian</p>
              </div>
            </div>
          </div>
          <div className="flex items-center gap-2">
            <button className="w-10 h-10 rounded-full flex items-center justify-center hover:bg-surface-container-low transition-colors text-on-surface-variant">
              <span className="material-symbols-outlined">call</span>
            </button>
            <button className="w-10 h-10 rounded-full flex items-center justify-center hover:bg-surface-container-low transition-colors text-on-surface-variant">
              <span className="material-symbols-outlined">videocam</span>
            </button>
            <button className="w-10 h-10 rounded-full flex items-center justify-center hover:bg-surface-container-low transition-colors text-on-surface-variant hidden sm:flex">
              <span className="material-symbols-outlined">more_vert</span>
            </button>
          </div>
        </header>

        {/* Chat Messages */}
        <div className="flex-1 overflow-y-auto p-4 md:p-6 bg-surface-container-lowest/50 space-y-4">
          <div className="text-center">
            <span className="text-[10px] font-bold text-on-surface-variant bg-surface-container-low px-3 py-1 rounded-full border border-outline-variant/20 uppercase tracking-wider">Today</span>
          </div>

          {messages.map((msg) => (
            <div key={msg.id} className={`flex ${msg.sender === 'user' ? 'justify-end' : 'justify-start'}`}>
              <div className={`max-w-[80%] md:max-w-[60%] flex flex-col ${msg.sender === 'user' ? 'items-end' : 'items-start'}`}>
                <div className={`px-4 py-2.5 rounded-2xl text-sm shadow-sm ${msg.sender === 'user' ? 'bg-primary text-white rounded-br-sm' : 'bg-surface-container text-on-surface border border-outline-variant/20 rounded-bl-sm'}`}>
                  {msg.text}
                </div>
                <span className="text-[10px] text-on-surface-variant mt-1 font-medium px-1">{msg.time}</span>
              </div>
            </div>
          ))}
          <div ref={messagesEndRef} />
        </div>

        {/* Chat Input */}
        <div className="bg-surface-container-lowest p-4 border-t border-outline-variant/30 shrink-0">
          <form onSubmit={handleSend} className="max-w-4xl mx-auto flex items-end gap-2 bg-surface-container-low border border-outline-variant/50 rounded-2xl p-1.5 focus-within:border-primary focus-within:ring-1 focus-within:ring-primary/30 transition-all">
            <button type="button" className="p-2 text-on-surface-variant hover:text-primary transition-colors rounded-xl shrink-0">
              <span className="material-symbols-outlined">attach_file</span>
            </button>
            <textarea 
              value={input}
              onChange={(e) => setInput(e.target.value)}
              onKeyDown={(e) => {
                if(e.key === 'Enter' && !e.shiftKey) {
                  e.preventDefault();
                  handleSend(e);
                }
              }}
              placeholder="Type a message..." 
              className="flex-1 bg-transparent border-none focus:ring-0 resize-none py-2.5 px-2 text-sm max-h-[120px]" 
              rows="1"
            />
            <button type="submit" disabled={!input.trim()} className="p-2.5 bg-primary text-white rounded-xl hover:bg-surface-tint transition-colors shrink-0 disabled:opacity-50 disabled:cursor-not-allowed">
              <span className="material-symbols-outlined text-[20px]">send</span>
            </button>
          </form>
        </div>
      </main>
    </div>
  );
};

export default LiveChat;

